rnd=math.random

particles={}

function TIC()
 cls(8)
 drawParticles()

	for i=1,2 do
	 x=rnd(-20,260)
		y=-5
  part(x,y,rnd(2,10))
	end
end

function part(x,y,c)
 table.insert(particles,
	 {t="rain",x=x,y=y,d=math.pi/2+rnd()*math.pi/8,
		c=rnd(12,14),ftl=80+rnd(90),s=5+rnd(2)})
end

function part2(x,y)
 table.insert(particles,
	 {t="drop",x=x,y=y,d=math.pi/2+rnd()*math.pi/8,
		c=c,ftl=30,s=3+rnd()})
end

function drawParticles()
 toDelete={}
 for i,p in ipairs(particles) do
  if p.t=="rain" then
	  l=p.s*2
	  line(p.x,p.y,p.x-math.cos(p.d)*l,
	   p.y-math.sin(p.d)*l,p.c) 
  
	  p.x=p.x+math.cos(p.d)*p.s
	  p.y=p.y+math.sin(p.d)*p.s
  else
   c=10
   if p.ftl<10 then c=9 end
   if p.ftl<5 then c=8 end
   ellib(p.x,p.y,8-p.ftl/5,4-p.ftl/10,c)
  end
  
  if p.t=="rain" then
	  if p.y>=p.ftl then
	   table.insert(toDelete,i)
			 part2(p.x,p.y)
	  end
		elseif p.t=="drop" then
		 p.ftl=p.ftl-1
		 if p.ftl<=0 then
	   table.insert(toDelete,i)
			end			
		end
 end
 for i=#toDelete,1,-1 do
  local p=particles[toDelete[i]]
  table.remove(particles,toDelete[i])
 end
end
